    SplashRenderer aether$getSplash();

    @Accessor("splash")
    void aether$setSplash(SplashRenderer splash);

    @Mutable
    @Accessor("fading")
    void aether$setFading(boolean fading);

    @Accessor("logoRenderer")
    LogoRenderer aether$getLogoRenderer();

    @Mutable
    @Accessor("logoRenderer")
